impl Parser<'_> {
    /// Parses the input string into a SQL statement AST. The entire string must
    /// be parsed as a single statement, ending with an optional semicolon.
    pub fn parse(statement: &str) -> Result<ast::Statement> {
        let mut parser = Parser::new(statement);
        let stmt = parser.parse_statement()?;
        // Ensure we've consumed all input (except optional semicolon)
        parser.skip(Token::Semicolon);
        if parser.peek()?.is_some() {
            return errinput!("unexpected token after statement");
        }
        Ok(stmt)
    }

    /// Parse the input string into a SQL expression AST. The entire string must
    /// be parsed as a single expression. Only used in tests.
    #[cfg(test)]
    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
        let mut parser = Parser::new(expr);
        let e = parser.parse_expression()?;
        // Ensure we've consumed all input
        if parser.peek()?.is_some() {
            return errinput!("unexpected token after expression");
        }
        Ok(e)
    }

    /// Creates a new parser for the given raw SQL string.
    fn new(input: &str) -> Parser<'_> {
        Parser {
            lexer: Lexer::new(input).peekable(),
        }
    }

    /// Fetches the next lexer token, or errors if none is found.
    fn next(&mut self) -> Result<Token> {
        self.lexer.next().unwrap_or_else(|| errinput!("unexpected end of input"))
    }

    /// Returns the next identifier, or errors if not found.
    fn next_ident(&mut self) -> Result<String> {
        match self.next()? {
            Token::Ident(s) => Ok(s),
            Token::Keyword(k) => Ok(k.to_string()),
            t => errinput!("expected identifier, got {t}"),
        }
    }

    /// Returns the next lexer token if it satisfies the predicate.
    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
        match self.lexer.peek() {
            Some(Ok(t)) if predicate(t) => self.lexer.next().unwrap(),
            _ => None,
        }
    }

    /// Passes the next lexer token through the closure, consuming it if the
    /// closure returns Some. Returns the result of the closure.
    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        match self.lexer.peek() {
            Some(Ok(t)) => {
                if let Some(result) = f(t) {
                    self.lexer.next();
                    Some(result)
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// Returns the next keyword if there is one.
    fn next_if_keyword(&mut self) -> Option<Keyword> {
        self.next_if_map(|t| match t {
            Token::Keyword(k) => Some(*k),
            _ => None,
        })
    }

    /// Consumes the next lexer token if it is the given token, returning true.
    fn next_is(&mut self, token: Token) -> bool {
        self.next_if(|t| t == &token).is_some()
    }

    /// Consumes the next lexer token if it's the expected token, or errors.
    fn expect(&mut self, expect: Token) -> Result<()> {
        let got = self.next()?;
        if got == expect {
            Ok(())
        } else {
            errinput!("expected {expect}, got {got}")
        }
    }

    /// Consumes the next lexer token if it is the given token. Equivalent to
    /// next_is(), but expresses intent better.
    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    /// Peeks the next lexer token if any, but transposes it for convenience.
    fn peek(&mut self) -> Result<Option<&Token>> {
        match self.lexer.peek() {
            Some(Ok(t)) => Ok(Some(t)),
            Some(Err(e)) => Err(e.clone()),
            None => Ok(None),
        }
    }

    /// Parses a SQL statement.
    fn parse_statement(&mut self) -> Result<ast::Statement> {
        let keyword = self.next_if_keyword().ok_or_else(|| errinput!("unexpected end of input"))?;

        match keyword {
            Keyword::Begin => self.parse_begin(),
            Keyword::Commit => self.parse_commit(),
            Keyword::Rollback => self.parse_rollback(),
            Keyword::Explain => self.parse_explain(),
            Keyword::Create => self.parse_create_table(),
            Keyword::Drop => self.parse_drop_table(),
            Keyword::Delete => self.parse_delete(),
            Keyword::Insert => self.parse_insert(),
            Keyword::Update => self.parse_update(),
            Keyword::Select => self.parse_select(),
            _ => errinput!("unexpected keyword {keyword}"),
        }
    }

    /// Parses a BEGIN statement.
    fn parse_begin(&mut self) -> Result<ast::Statement> {
        let read_only = self.next_if_keyword() == Some(Keyword::Read);
        if read_only {
            self.expect(Token::Keyword(Keyword::Write))?;
        }

        let as_of = if self.next_if_keyword() == Some(Keyword::As) {
            self.expect(Token::Keyword(Keyword::Of))?;
            self.expect(Token::Keyword(Keyword::System))?;
            self.expect(Token::Keyword(Keyword::Version))?;
            let version = self.next()?;
            match version {
                Token::Number(s) => Some(s.parse::<u64>().map_err(|_| errinput!("invalid version number"))?),
                _ => return errinput!("expected version number"),
            }
        } else {
            None
        };

        Ok(ast::Statement::Begin { read_only, as_of })
    }

    /// Parses a COMMIT statement.
    fn parse_commit(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Commit)
    }

    /// Parses a ROLLBACK statement.
    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Rollback)
    }

    /// Parses an EXPLAIN statement.
    fn parse_explain(&mut self) -> Result<ast::Statement> {
        let stmt = self.parse_statement()?;
        Ok(ast::Statement::Explain(Box::new(stmt)))
    }

    /// Parses a CREATE TABLE statement.
    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;

        self.expect(Token::OpenParen)?;

        let mut columns = Vec::new();
        loop {
            if self.next_is(Token::CloseParen) {
                break;
            }

            if !columns.is_empty() {
                self.expect(Token::Comma)?;
            }

            columns.push(self.parse_create_table_column()?);
        }

        self.expect(Token::CloseParen)?;

        Ok(ast::Statement::CreateTable { name, columns })
    }

    /// Parses a CREATE TABLE column definition.
    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;

        // Parse datatype
        let datatype = match self.next()? {
            Token::Keyword(Keyword::Boolean | Keyword::Bool) => DataType::Boolean,
            Token::Keyword(Keyword::Int | Keyword::Integer) => DataType::Integer,
            Token::Keyword(Keyword::Float | Keyword::Double) => DataType::Float,
            Token::Keyword(Keyword::String | Keyword::Text | Keyword::Varchar) => DataType::String,
            t => return errinput!("expected datatype, got {t}"),
        };

        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;

        // Parse column constraints
        loop {
            match self.peek()? {
                Some(Token::Keyword(Keyword::Primary)) => {
                    self.next()?;
                    self.expect(Token::Keyword(Keyword::Key))?;
                    primary_key = true;
                }
                Some(Token::Keyword(Keyword::Not)) => {
                    self.next()?;
                    self.expect(Token::Keyword(Keyword::Null))?;
                    nullable = Some(false);
                }
                Some(Token::Keyword(Keyword::Null)) => {
                    self.next()?;
                    nullable = Some(true);
                }
                Some(Token::Keyword(Keyword::Default)) => {
                    self.next()?;
                    default = Some(self.parse_expression()?);
                }
                Some(Token::Keyword(Keyword::Unique)) => {
                    self.next()?;
                    unique = true;
                }
                Some(Token::Keyword(Keyword::Index)) => {
                    self.next()?;
                    index = true;
                }
                Some(Token::Keyword(Keyword::References)) => {
                    self.next()?;
                    references = Some(self.next_ident()?);
                }
                _ => break,
            }
        }

        Ok(ast::Column {
            name,
            datatype,
            primary_key,
            nullable,
            default,
            unique,
            index,
            references,
        })
    }

    /// Parses a DROP TABLE statement.
    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;

        let if_exists = self.next_if_keyword() == Some(Keyword::If);
        if if_exists {
            self.expect(Token::Keyword(Keyword::Exists))?;
        }

        let name = self.next_ident()?;

        Ok(ast::Statement::DropTable { name, if_exists })
    }

    /// Parses a DELETE statement.
    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::From))?;
        let table = self.next_ident()?;

        let r#where = if self.next_if_keyword() == Some(Keyword::Where) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Delete { table, r#where })
    }

    /// Parses an INSERT statement.
    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Into))?;
        let table = self.next_ident()?;

        let columns = if self.next_is(Token::OpenParen) {
            self.expect(Token::OpenParen)?;
            let mut cols = Vec::new();
            loop {
                if self.next_is(Token::CloseParen) {
                    break;
                }
                if !cols.is_empty() {
                    self.expect(Token::Comma)?;
                }
                cols.push(self.next_ident()?);
            }
            self.expect(Token::CloseParen)?;
            Some(cols)
        } else {
            None
        };

        self.expect(Token::Keyword(Keyword::Values))?;

        let mut values = Vec::new();
        loop {
            self.expect(Token::OpenParen)?;
            let mut row = Vec::new();
            loop {
                if self.next_is(Token::CloseParen) {
                    break;
                }
                if !row.is_empty() {
                    self.expect(Token::Comma)?;
                }
                row.push(self.parse_expression()?);
            }
            self.expect(Token::CloseParen)?;
            values.push(row);

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        Ok(ast::Statement::Insert { table, columns, values })
    }

    /// Parses an UPDATE statement.
    fn parse_update(&mut self) -> Result<ast::Statement> {
        let table = self.next_ident()?;

        self.expect(Token::Keyword(Keyword::Set))?;

        let mut set = std::collections::BTreeMap::new();
        loop {
            let column = self.next_ident()?;
            self.expect(Token::Equal)?;

            let value = if self.next_if_keyword() == Some(Keyword::Default) {
                None
            } else {
                Some(self.parse_expression()?)
            };

            set.insert(column, value);

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        let r#where = if self.next_if_keyword() == Some(Keyword::Where) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        Ok(ast::Statement::Update { table, set, r#where })
    }

    /// Parses a SELECT statement.
    fn parse_select(&mut self) -> Result<ast::Statement> {
        let select = self.parse_select_clause()?;

        let from = if self.next_if_keyword() == Some(Keyword::From) {
            self.parse_from_clause()?
        } else {
            Vec::new()
        };

        let r#where = if self.next_if_keyword() == Some(Keyword::Where) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        let group_by = if self.next_if_keyword() == Some(Keyword::Group) {
            self.expect(Token::Keyword(Keyword::By))?;
            self.parse_group_by_clause()?
        } else {
            Vec::new()
        };

        let having = if self.next_if_keyword() == Some(Keyword::Having) {
            Some(self.parse_expression()?)
        } else {
            None
        };

        let order_by = if self.next_if_keyword() == Some(Keyword::Order) {
            self.expect(Token::Keyword(Keyword::By))?;
            self.parse_order_by_clause()?
        } else {
            Vec::new()
        };

        let offset = if self.next_if_keyword() == Some(Keyword::Offset) {
            Some(self.parse_offset_clause()?)
        } else {
            None
        };

        let limit = if self.next_if_keyword() == Some(Keyword::Limit) {
            Some(self.parse_limit_clause()?)
        } else {
            None
        };

        Ok(ast::Statement::Select {
            select,
            from,
            r#where,
            group_by,
            having,
            order_by,
            offset,
            limit,
        })
    }

    /// Parses a SELECT clause, if present.
    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();

        loop {
            if !select.is_empty() {
                self.expect(Token::Comma)?;
            }

            let expr = self.parse_expression()?;

            let alias = if self.next_if_keyword() == Some(Keyword::As) {
                Some(self.next_ident()?)
            } else {
                // Check for unquoted alias (identifier without AS)
                match self.peek()? {
                    Some(Token::Ident(s)) => {
                        self.next()?;
                        Some(s.clone())
                    }
                    _ => None,
                }
            };

            select.push((expr, alias));

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        Ok(select)
    }

    /// Parses a FROM clause, if present.
    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        let mut from = Vec::new();

        from.push(self.parse_from_table()?);

        // Parse joins
        while let Some(join_type) = self.parse_from_join()? {
            let right = Box::new(self.parse_from_table()?);
            let left = if from.is_empty() {
                return errinput!("JOIN without FROM table");
            } else {
                Box::new(from.pop().unwrap())
            };

            // Get join condition
            let predicate = if self.next_if_keyword() == Some(Keyword::On) {
                Some(self.parse_expression()?)
            } else {
                None
            };

            from.push(ast::From::Join { left, right, r#type: join_type, predicate });
        }

        Ok(from)
    }

    // Parses a FROM table.
    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;

        let alias = if self.next_if_keyword() == Some(Keyword::As) {
            Some(self.next_ident()?)
        } else {
            // Check for unquoted alias
            match self.peek()? {
                Some(Token::Ident(s)) => {
                    self.next()?;
                    Some(s.clone())
                }
                _ => None,
            }
        };

        Ok(ast::From::Table { name, alias })
    }

    // Parses a FROM JOIN type, if present.
    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        let join_type = match self.peek()? {
            Some(Token::Keyword(Keyword::Cross)) => {
                self.next()?;
                self.expect(Token::Keyword(Keyword::Join))?;
                ast::JoinType::Cross
            }
            Some(Token::Keyword(Keyword::Inner)) => {
                self.next()?;
                self.expect(Token::Keyword(Keyword::Join))?;
                ast::JoinType::Inner
            }
            Some(Token::Keyword(Keyword::Left)) => {
                self.next()?;
                if self.next_if_keyword() == Some(Keyword::Outer) {
                    // LEFT OUTER JOIN
                }
                self.expect(Token::Keyword(Keyword::Join))?;
                ast::JoinType::Left
            }
            Some(Token::Keyword(Keyword::Right)) => {
                self.next()?;
                if self.next_if_keyword() == Some(Keyword::Outer) {
                    // RIGHT OUTER JOIN
                }
                self.expect(Token::Keyword(Keyword::Join))?;
                ast::JoinType::Right
            }
            _ => return Ok(None),
        };

        Ok(Some(join_type))
    }

    /// Parses a WHERE clause, if present.
    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Where) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses a GROUP BY clause, if present.
    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        let mut group_by = Vec::new();

        loop {
            group_by.push(self.parse_expression()?);

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        Ok(group_by)
    }

    /// Parses a HAVING clause, if present.
    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Having) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    /// Parses an ORDER BY clause, if present.
    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        let mut order_by = Vec::new();

        loop {
            let expr = self.parse_expression()?;

            let direction = if self.next_if_keyword() == Some(Keyword::Asc) {
                ast::Direction::Ascending
            } else if self.next_if_keyword() == Some(Keyword::Desc) {
                ast::Direction::Descending
            } else {
                ast::Direction::Ascending // default
            };

            order_by.push((expr, direction));

            if !self.next_is(Token::Comma) {
                break;
            }
        }

        Ok(order_by)
    }

    /// Parses a LIMIT clause, if present.
    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an OFFSET clause, if present.
    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        Ok(Some(self.parse_expression()?))
    }

    /// Parses an expression using the precedence climbing algorithm.
    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(0)
    }

    /// Parses an expression at the given minimum precedence.
    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        let mut lhs = self.parse_expression_atom()?;

        loop {
            // Check for prefix operators
            if let Some(prefix_op) = self.parse_prefix_operator_at(min_precedence) {
                let rhs = self.parse_expression_at(prefix_op.precedence())?;
                lhs = prefix_op.into_expression(rhs);
                continue;
            }

            // Check for infix operators
            if let Some(infix_op) = self.parse_infix_operator_at(min_precedence) {
                let precedence = infix_op.precedence();
                let associativity = infix_op.associativity();

                let rhs = self.parse_expression_at(precedence + associativity)?;
                lhs = infix_op.into_expression(lhs, rhs);
                continue;
            }

            // Check for postfix operators
            if let Some(postfix_op) = self.parse_postfix_operator_at(min_precedence)? {
                lhs = postfix_op.into_expression(lhs);
                continue;
            }

            break;
        }

        Ok(lhs)
    }

    /// Parses an expression atom.
    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        let token = self.next()?;

        match token {
            Token::Number(s) => {
                // Try to parse as integer first, then float
                if let Ok(i) = s.parse::<i64>() {
                    Ok(ast::Expression::Literal(ast::Literal::Integer(i)))
                } else if let Ok(f) = s.parse::<f64>() {
                    Ok(ast::Expression::Literal(ast::Literal::Float(f)))
                } else {
                    errinput!("invalid number: {s}")
                }
            }
            Token::String(s) => Ok(ast::Expression::Literal(ast::Literal::String(s))),
            Token::Ident(s) => {
                // Check if it's a keyword that can be used as an identifier
                if let Ok(keyword) = Keyword::try_from(s.as_str()) {
                    match keyword {
                        Keyword::True => Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
                        Keyword::False => Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
                        Keyword::Null => Ok(ast::Expression::Literal(ast::Literal::Null)),
                        Keyword::NaN => Ok(ast::Expression::Literal(ast::Literal::Float(f64::NAN))),
                        Keyword::Infinity => Ok(ast::Expression::Literal(ast::Literal::Float(f64::INFINITY))),
                        _ => {
                            // Check for qualified column name
                            if self.next_is(Token::Period) {
                                let column = self.next_ident()?;
                                Ok(ast::Expression::Column(Some(s), column))
                            } else {
                                Ok(ast::Expression::Column(None, s))
                            }
                        }
                    }
                } else {
                    // Check for qualified column name
                    if self.next_is(Token::Period) {
                        let column = self.next_ident()?;
                        Ok(ast::Expression::Column(Some(s), column))
                    } else {
                        Ok(ast::Expression::Column(None, s))
                    }
                }
            }
            Token::Asterisk => Ok(ast::Expression::All),
            Token::OpenParen => {
                let expr = self.parse_expression()?;
                self.expect(Token::CloseParen)?;
                Ok(expr)
            }
            Token::Keyword(Keyword::True) => Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
            Token::Keyword(Keyword::False) => Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
            Token::Keyword(Keyword::Null) => Ok(ast::Expression::Literal(ast::Literal::Null)),
            Token::Keyword(Keyword::NaN) => Ok(ast::Expression::Literal(ast::Literal::Float(f64::NAN))),
            Token::Keyword(Keyword::Infinity) => Ok(ast::Expression::Literal(ast::Literal::Float(f64::INFINITY))),
            t => errinput!("unexpected token {t} in expression"),
        }
    }

    /// Parses a prefix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_prefix_operator_at(&mut self, min_precedence: Precedence) -> Option<PrefixOperator> {
        let op = match self.peek()? {
            Token::Minus => PrefixOperator::Minus,
            Token::Plus => PrefixOperator::Plus,
            Token::Keyword(Keyword::Not) => PrefixOperator::Not,
            _ => return None,
        };

        if op.precedence() >= min_precedence {
            self.next();
            Some(op)
        } else {
            None
        }
    }

    /// Parses an infix operator, if there is one and its precedence is at least
    /// min_precedence.
    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        let op = match self.peek()? {
            Token::Keyword(Keyword::And) => InfixOperator::And,
            Token::Keyword(Keyword::Or) => InfixOperator::Or,
            Token::Equal => InfixOperator::Equal,
            Token::NotEqual => InfixOperator::NotEqual,
            Token::LessOrGreaterThan => InfixOperator::NotEqual,
            Token::LessThan => InfixOperator::LessThan,
            Token::LessThanOrEqual => InfixOperator::LessThanOrEqual,
            Token::GreaterThan => InfixOperator::GreaterThan,
            Token::GreaterThanOrEqual => InfixOperator::GreaterThanOrEqual,
            Token::Keyword(Keyword::Like) => InfixOperator::Like,
            Token::Plus => InfixOperator::Add,
            Token::Minus => InfixOperator::Subtract,
            Token::Asterisk => InfixOperator::Multiply,
            Token::Slash => InfixOperator::Divide,
            Token::Percent => InfixOperator::Remainder,
            Token::Caret => InfixOperator::Exponentiate,
            _ => return None,
        };

        if op.precedence() >= min_precedence {
            self.next();
            Some(op)
        } else {
            None
        }
    }

    /// Parses a postfix operator, if there is one and its precedence is at
    /// least min_precedence.
    fn parse_postfix_operator_at(
        &mut self,
        min_precedence: Precedence,
    ) -> Result<Option<PostfixOperator>> {
        let op = match self.peek()? {
            Token::Exclamation => {
                self.next()?;
                PostfixOperator::Factorial
            }
            Token::Keyword(Keyword::Is) => {
                self.next()?;
                let not = self.next_is(Token::Keyword(Keyword::Not));
                let literal = match self.next()? {
                    Token::Keyword(Keyword::Null) => ast::Literal::Null,
                    Token::Keyword(Keyword::NaN) => ast::Literal::Float(f64::NAN),
                    t => return errinput!("expected NULL or NaN after IS, got {t}"),
                };
                if not {
                    PostfixOperator::IsNot(literal)
                } else {
                    PostfixOperator::Is(literal)
                }
            }
            _ => return Ok(None),
        };

        if op.precedence() >= min_precedence {
            Ok(Some(op))
        } else {
            Ok(None)
        }
    }
}

